package modelregistry

import (
	"time"

	"github.com/easel/fizeau/internal/modelcatalog"
)

// Source records how a model ID was discovered.
type Source string

const (
	SourceNativeAPI  Source = "native_api"
	SourceHarnessPTY Source = "harness_pty"
	SourcePropsAPI   Source = "props_api"
)

// ModelStatus records the provider runtime state relevant to routing.
type ModelStatus string

const (
	StatusAvailable   ModelStatus = "available"
	StatusRateLimited ModelStatus = "rate_limited"
	StatusUnreachable ModelStatus = "unreachable"
	StatusUnknown     ModelStatus = "unknown"
)

// KnownModel is one discovered provider/model identity enriched with catalog
// metadata when the catalog knows the model.
type KnownModel struct {
	Provider   string
	ID         string
	Configured bool

	DiscoveredVia Source
	DiscoveredAt  time.Time

	Family     string
	Version    []int
	Tier       modelcatalog.Tier
	PreRelease bool

	Power            int
	CostInputPerM    float64
	CostOutputPerM   float64
	ContextWindow    int
	ReasoningLevels  []string
	QuotaPool        string
	QuotaRemaining   *int
	RecentP50Latency time.Duration

	Status          ModelStatus
	AutoRoutable    bool
	ExactPinOnly    bool
	ExclusionReason string
}

// ModelSnapshot is the in-memory model registry view assembled from discovery
// cache entries and catalog metadata.
type ModelSnapshot struct {
	Models  []KnownModel
	AsOf    time.Time
	Sources map[string]SourceMeta
}

// SourceMeta summarizes cache state for a discovery source.
type SourceMeta struct {
	LastRefreshedAt time.Time
	Stale           bool
	Error           string
}

---ASSEMBLE---
package modelregistry

import (
	"context"
	"os/exec"
	"sort"
	"time"

	"github.com/easel/fizeau/internal/config"
	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/modelcatalog"
)

// RefreshMode controls whether Assemble refreshes stale source cache data.
type RefreshMode int

const (
	// RefreshBackground preserves the default stale-while-revalidate behavior:
	// return cached data immediately and refresh stale sources in the background.
	RefreshBackground RefreshMode = iota
	// RefreshNone returns cached data only.
	RefreshNone
	// RefreshForce refreshes sources synchronously before reading them.
	RefreshForce
)

// AssembleOptions controls snapshot assembly behavior.
type AssembleOptions struct {
	Refresh RefreshMode
}

// Assemble builds a ModelSnapshot from configured providers, cache-backed
// discovery, runtime status cache state, and model catalog metadata.
func Assemble(ctx context.Context, cfg *config.Config, cat *modelcatalog.Catalog, cache *discoverycache.Cache) (ModelSnapshot, error) {
	return AssembleWithOptions(ctx, cfg, cat, cache, AssembleOptions{Refresh: RefreshBackground})
}

// AssembleWithOptions builds a ModelSnapshot with explicit cache refresh
// behavior for CLI and routing consumers.
func AssembleWithOptions(ctx context.Context, cfg *config.Config, cat *modelcatalog.Catalog, cache *discoverycache.Cache, opts AssembleOptions) (ModelSnapshot, error) {
	asOf := nowUTC()
	snapshot := ModelSnapshot{
		AsOf:    asOf,
		Sources: map[string]SourceMeta{},
	}
	if cfg == nil {
		return snapshot, nil
	}

	providers := enumerateProviders(cfg)
	names := make([]string, 0, len(providers))
	for name := range providers {
		names = append(names, name)
	}
	sort.Strings(names)

	for _, providerName := range names {
		pcfg := providers[providerName]
		discovered := discoverProvider(ctx, providerName, pcfg, cache, opts)
		for source, meta := range discovered.Sources {
			snapshot.Sources[source] = meta
		}
		includeByDefault := effectiveProviderIncludeByDefault(providerName, pcfg, cat)
		status := providerStatus(cache, providerName)
		for _, discoveredModel := range discovered.Models {
			model := KnownModel{
				Provider:      providerName,
				ID:            discoveredModel.ID,
				Configured:    discoveredModel.Configured,
				DiscoveredVia: discoveredModel.Via,
				DiscoveredAt:  discoveredModel.DiscoveredAt,
				Status:        status,
			}
			model = enrichModel(model, includeByDefault, cat)
			model = attachRuntimeSignals(model, cache)
			snapshot.Models = append(snapshot.Models, model)
		}
	}
	sort.Slice(snapshot.Models, func(i, j int) bool {
		if snapshot.Models[i].Provider != snapshot.Models[j].Provider {
			return snapshot.Models[i].Provider < snapshot.Models[j].Provider
		}
		return snapshot.Models[i].ID < snapshot.Models[j].ID
	})
	return snapshot, nil
}

// ActiveSources returns the cache sources that are currently configured and
// should be preserved by cache garbage collection.
func ActiveSources(cfg *config.Config) []discoverycache.Source {
	if cfg == nil {
		return nil
	}
	providers := enumerateProviders(cfg)
	names := make([]string, 0, len(providers))
	for name := range providers {
		names = append(names, name)
	}
	sort.Strings(names)

	sources := make([]discoverycache.Source, 0, len(names)*2)
	for _, providerName := range names {
		pcfg := providers[providerName]
		switch normalizeProviderType(pcfg.Type) {
		case "claude", "codex":
			sources = append(sources, discoverycache.Source{
				Tier:            "discovery",
				Name:            providerName,
				TTL:             discoveryTTLPTY,
				RefreshDeadline: discoveryRefreshDeadlinePTY,
			})
		case "openai", "openrouter", "vidar-ds4", "sindri-llamacpp", "ds4", "lmstudio", "llama-server", "omlx", "rapid-mlx", "vllm", "ollama", "minimax", "qwen", "zai":
			sources = append(sources, discoverySource(providerName, discoveryTTLForProvider(pcfg), discoveryRefreshDeadlineHTTP))
			if normalizeProviderType(pcfg.Type) == "ds4" || normalizeProviderType(pcfg.Type) == "vidar-ds4" {
				sources = append(sources, discoverySource(providerName+"-props", discoveryTTLHTTPLocal, discoveryRefreshDeadlineHTTP))
			}
		default:
			if pcfg.Model != "" {
				sources = append(sources, discoverySource(providerName, discoveryTTLHTTPRemote, discoveryRefreshDeadlineHTTP))
			}
		}
		sources = append(sources, discoverycache.Source{
			Tier:            "runtime",
			Name:            providerName,
			TTL:             5 * time.Minute,
			RefreshDeadline: 5 * time.Second,
		})
	}
	return sources
}

func enumerateProviders(cfg *config.Config) map[string]config.ProviderConfig {
	out := make(map[string]config.ProviderConfig, len(cfg.Providers)+2)
	for name, pc := range cfg.Providers {
		out[name] = pc
	}
	addImplicitHarness(out, "claude-subscription", "claude", "claude")
	addImplicitHarness(out, "codex-subscription", "codex", "codex")
	return out
}

func addImplicitHarness(providers map[string]config.ProviderConfig, name, providerType, binary string) {
	if _, exists := providers[name]; exists {
		return
	}
	if _, err := exec.LookPath(binary); err != nil {
		return
	}
	include := true
	providers[name] = config.ProviderConfig{
		Type:             providerType,
		IncludeByDefault: &include,
		Billing:          string(modelcatalog.BillingModelSubscription),
	}
}

---DISCOVERY---
package modelregistry

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/easel/fizeau/internal/config"
	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/modelref"
	openaiadapter "github.com/easel/fizeau/internal/provider/openai"
)

const (
	discoveryTTLHTTPRemote       = 24 * time.Hour
	discoveryTTLHTTPLocal        = time.Hour
	discoveryTTLPTY              = 24 * time.Hour
	discoveryRefreshDeadlineHTTP = 10 * time.Second
	discoveryRefreshDeadlinePTY  = 60 * time.Second
)

type discoveredModel struct {
	ID           string
	Configured   bool
	Via          Source
	DiscoveredAt time.Time
}

type providerDiscoveryResult struct {
	Models  []discoveredModel
	Sources map[string]SourceMeta
}

type discoveryPayload struct {
	CapturedAt      time.Time `json:"captured_at"`
	Models          []string  `json:"models,omitempty"`
	ReasoningLevels []string  `json:"reasoning_levels,omitempty"`
	Source          string    `json:"source,omitempty"`
}

func discoverProvider(ctx context.Context, providerName string, pc config.ProviderConfig, cache *discoverycache.Cache, opts AssembleOptions) providerDiscoveryResult {
	providerType := normalizeProviderType(pc.Type)
	switch providerType {
	case "claude", "codex":
		return discoverHarnessProvider(providerName, providerType, cache, opts)
	case "openai", "openrouter", "vidar-ds4", "sindri-llamacpp", "ds4", "lmstudio", "llama-server", "omlx", "rapid-mlx", "vllm", "ollama", "minimax", "qwen", "zai":
		result := discoverOpenAICompatibleProvider(ctx, providerName, pc, cache, opts)
		if providerType == "ds4" || providerType == "vidar-ds4" {
			result.merge(discoverPropsProvider(providerName, cache))
		}
		return result
	default:
		if strings.TrimSpace(pc.Model) == "" {
			return providerDiscoveryResult{Sources: map[string]SourceMeta{}}
		}
		return providerDiscoveryResult{
			Models: []discoveredModel{{
				ID:           strings.TrimSpace(pc.Model),
				Via:          SourceNativeAPI,
				DiscoveredAt: time.Now().UTC(),
			}},
			Sources: map[string]SourceMeta{
				providerName: {LastRefreshedAt: time.Now().UTC()},
			},
		}
	}
}

func discoverOpenAICompatibleProvider(ctx context.Context, providerName string, pc config.ProviderConfig, cache *discoverycache.Cache, opts AssembleOptions) providerDiscoveryResult {
	src := discoverySource(providerName, discoveryTTLForProvider(pc), discoveryRefreshDeadlineHTTP)
	if cache == nil {
		return providerDiscoveryResult{Sources: map[string]SourceMeta{providerName: {Stale: true, Error: "discovery cache is nil"}}}
	}
	if hasDiscoveryEndpoint(pc) {
		baseURL := strings.TrimRight(firstBaseURL(pc), "/")
		apiKey := pc.APIKey
		refresher := func(refreshCtx context.Context) ([]byte, error) {
			requestCtx := ctx
			if requestCtx == nil {
				requestCtx = refreshCtx
			}
			ids, err := openaiadapter.DiscoverModels(requestCtx, baseURL, apiKey)
			if err != nil {
				return nil, err
			}
			return json.Marshal(discoveryPayload{
				CapturedAt: time.Now().UTC(),
				Models:     ids,
				Source:     "openai-compatible:/v1/models",
			})
		}
		if opts.Refresh == RefreshForce {
			_ = cache.Refresh(src, refresher)
		} else if opts.Refresh != RefreshNone {
			cache.MaybeRefresh(src, refresher)
		}
	}
	result := readDiscoveryCache(cache, src, providerName, SourceNativeAPI)
	if result.Sources == nil {
		result.Sources = map[string]SourceMeta{}
	}
	if len(result.Models) == 0 && strings.TrimSpace(pc.Model) != "" {
		fallback := modelsFromIDs([]string{pc.Model}, SourceNativeAPI, time.Now().UTC(), providerName)
		for i := range fallback.Models {
			fallback.Models[i].Configured = true
		}
		result.Models = fallback.Models
		meta := result.Sources[providerName]
		if meta.LastRefreshedAt.IsZero() {
			meta.LastRefreshedAt = time.Now().UTC()
		}
		result.Sources[providerName] = meta
	}
	return result
}

func discoverPropsProvider(providerName string, cache *discoverycache.Cache) providerDiscoveryResult {
	if cache == nil {
		return providerDiscoveryResult{Sources: map[string]SourceMeta{providerName + ":props": {Stale: true, Error: "discovery cache is nil"}}}
	}
	src := discoverySource(providerName+"-props", discoveryTTLHTTPLocal, discoveryRefreshDeadlineHTTP)
	result := readDiscoveryCache(cache, src, providerName, SourcePropsAPI)
	renamed := make(map[string]SourceMeta, len(result.Sources))
	for _, meta := range result.Sources {
		renamed[providerName+":props"] = meta
	}
	result.Sources = renamed
	return result
}

func discoverHarnessProvider(providerName, providerType string, cache *discoverycache.Cache, opts AssembleOptions) providerDiscoveryResult {
	src := discoverycache.Source{
		Tier:            "discovery",
		Name:            providerName,
		TTL:             discoveryTTLPTY,
		RefreshDeadline: discoveryRefreshDeadlinePTY,
	}
	if cache == nil {
		snapshot, err := harnesses.CachedModelDiscoverySnapshot(providerType, harnesses.EmbeddedDiscoverySource)
		if err != nil {
			return providerDiscoveryResult{Sources: map[string]SourceMeta{providerName: {Stale: true, Error: err.Error()}}}
		}
		return modelsFromIDs(snapshot.Models, SourceHarnessPTY, snapshot.CapturedAt, providerName)
	}
	if opts.Refresh == RefreshForce {
		_ = cache.Refresh(src, func(context.Context) ([]byte, error) {
			snapshot, err := harnesses.CachedModelDiscoverySnapshot(providerType, harnesses.EmbeddedDiscoverySource)
			if err != nil {
				return nil, err
			}
			return json.Marshal(discoveryPayload{
				CapturedAt:      snapshot.CapturedAt,
				Models:          snapshot.Models,
				ReasoningLevels: snapshot.ReasoningLevels,
				Source:          snapshot.Source,
			})
		})
	}
	result := readDiscoveryCache(cache, src, providerName, SourceHarnessPTY)
	if len(result.Models) > 0 {
		return result
	}
	snapshot, err := harnesses.CachedModelDiscoverySnapshot(providerType, harnesses.EmbeddedDiscoverySource)
	if err != nil {
		if result.Sources == nil {
			result.Sources = map[string]SourceMeta{}
		}
		meta := result.Sources[providerName]
		meta.Error = err.Error()
		result.Sources[providerName] = meta
		return result
	}
	return modelsFromIDs(snapshot.Models, SourceHarnessPTY, snapshot.CapturedAt, providerName)
}

func readDiscoveryCache(cache *discoverycache.Cache, src discoverycache.Source, providerName string, via Source) providerDiscoveryResult {
	result := providerDiscoveryResult{Sources: map[string]SourceMeta{}}
	read, err := cache.Read(src)
	meta := SourceMeta{Stale: true}
	if read.Data != nil {
		meta.LastRefreshedAt = time.Now().Add(-read.Age).UTC()
		meta.Stale = read.Stale
	}
	if err != nil {
		meta.Error = err.Error()
		result.Sources[src.Name] = meta
		return result
	}
	result.Sources[src.Name] = meta
	if read.Data == nil {
		return result
	}
	ids, capturedAt, err := parseDiscoveryIDs(read.Data, providerName)
	if err != nil {
		meta.Error = err.Error()
		result.Sources[src.Name] = meta
		return result
	}
	if !capturedAt.IsZero() {
		meta.LastRefreshedAt = capturedAt.UTC()
		result.Sources[src.Name] = meta
	}
	result.Models = modelsFromIDs(ids, via, discoveredAt(capturedAt, meta.LastRefreshedAt), providerName).Models
	return result
}

func parseDiscoveryIDs(data []byte, providerName string) ([]string, time.Time, error) {
	data = bytes.TrimSpace(data)
	if len(data) == 0 {
		return nil, time.Time{}, nil
	}
	var list []string
	if err := json.Unmarshal(data, &list); err == nil {
		return uniqueSortedStrings(list), time.Time{}, nil
	}
	var payload discoveryPayload
	if err := json.Unmarshal(data, &payload); err == nil && (len(payload.Models) > 0 || !payload.CapturedAt.IsZero()) {
		return uniqueSortedStrings(payload.Models), payload.CapturedAt, nil
	}
	var byRef map[string]json.RawMessage
	if err := json.Unmarshal(data, &byRef); err != nil {
		return nil, time.Time{}, fmt.Errorf("decode discovery cache: %w", err)
	}
	ids := make([]string, 0, len(byRef))
	var capturedAt time.Time
	for key, raw := range byRef {
		includeValueFields := true
		if ref, err := modelref.Parse(key); err == nil {
			includeValueFields = ref.Provider == providerName
			if ref.Provider == providerName {
				ids = append(ids, ref.ID)
			}
		}
		if !includeValueFields {
			continue
		}
		var item struct {
			ID         string    `json:"id"`
			ModelID    string    `json:"model_id"`
			CapturedAt time.Time `json:"captured_at"`
		}
		if err := json.Unmarshal(raw, &item); err == nil {
			if item.ID != "" {
				ids = append(ids, item.ID)
			}
			if item.ModelID != "" {
				ids = append(ids, item.ModelID)
			}
			if capturedAt.IsZero() && !item.CapturedAt.IsZero() {
				capturedAt = item.CapturedAt
			}
		}
	}
	return uniqueSortedStrings(ids), capturedAt, nil
}

---CLI---
package agentcli

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"text/tabwriter"
	"time"

	agentConfig "github.com/easel/fizeau/internal/config"
	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/modelregistry"
	"github.com/easel/fizeau/internal/runtimesignals"
)

type modelsCommandOptions struct {
	JSON         bool
	Provider     string
	PowerMin     int
	PowerMax     int
	IncludeNoise bool
	Refresh      modelregistry.RefreshMode
	Ref          string
}

type modelDetail struct {
	CanonicalID       string                   `json:"canonical_id"`
	KnownModel        modelregistry.KnownModel `json:"known_model"`
	RawDiscoveryData  json.RawMessage          `json:"raw_discovery_data,omitempty"`
	CatalogEntry      *modelcatalog.ModelEntry `json:"catalog_entry,omitempty"`
	RuntimeSignal     *runtimesignals.Signal   `json:"runtime_signal,omitempty"`
	AutoRoutable      autoRoutableComposition  `json:"auto_routable"`
	SourceMeta        modelregistry.SourceMeta `json:"source_meta"`
	SnapshotGenerated time.Time                `json:"snapshot_generated_at"`
}

type autoRoutableComposition struct {
	AutoRoutable bool   `json:"auto_routable"`
	BlockedBy    string `json:"blocked_by,omitempty"`
	Provider     bool   `json:"provider"`
	Catalog      bool   `json:"catalog"`
	Status       bool   `json:"status"`
}

func cmdModels(workDir string, args []string) int {
	opts, err := parseModelsArgs(args)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	snapshot, cfg, cat, cache, err := loadModelSnapshot(workDir, opts.Refresh)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	if opts.Ref != "" {
		return cmdModelsDetail(snapshot, cfg, cat, cache, opts)
	}
	return cmdModelsList(snapshot, opts)
}

func parseModelsArgs(args []string) (modelsCommandOptions, error) {
	opts := modelsCommandOptions{Refresh: modelregistry.RefreshBackground}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "--json":
			opts.JSON = true
		case arg == "--refresh":
			opts.Refresh = modelregistry.RefreshForce
		case arg == "--no-refresh":
			if opts.Refresh == modelregistry.RefreshForce {
				return opts, fmt.Errorf("--refresh and --no-refresh cannot be combined")
			}
			opts.Refresh = modelregistry.RefreshNone
		case arg == "--include-noise":
			opts.IncludeNoise = true
		case arg == "--provider":
			i++
			if i >= len(args) {
				return opts, fmt.Errorf("--provider requires a value")
			}
			opts.Provider = args[i]
		case strings.HasPrefix(arg, "--provider="):
			opts.Provider = strings.TrimPrefix(arg, "--provider=")
		case arg == "--power-min":
			i++
			if i >= len(args) {
				return opts, fmt.Errorf("--power-min requires a value")
			}
			value, err := strconv.Atoi(args[i])
			if err != nil {
				return opts, fmt.Errorf("--power-min: %w", err)
			}
			opts.PowerMin = value
		case strings.HasPrefix(arg, "--power-min="):
			value, err := strconv.Atoi(strings.TrimPrefix(arg, "--power-min="))
			if err != nil {
				return opts, fmt.Errorf("--power-min: %w", err)
			}
			opts.PowerMin = value
		case arg == "--power-max":
			i++
			if i >= len(args) {
				return opts, fmt.Errorf("--power-max requires a value")
			}
			value, err := strconv.Atoi(args[i])
			if err != nil {
				return opts, fmt.Errorf("--power-max: %w", err)
			}
			opts.PowerMax = value
		case strings.HasPrefix(arg, "--power-max="):
			value, err := strconv.Atoi(strings.TrimPrefix(arg, "--power-max="))
			if err != nil {
				return opts, fmt.Errorf("--power-max: %w", err)
			}
			opts.PowerMax = value
		case strings.HasPrefix(arg, "-"):
			return opts, fmt.Errorf("unknown models flag %s", arg)
		default:
			if opts.Ref != "" {
				return opts, fmt.Errorf("models accepts at most one ref")
			}
			opts.Ref = arg
		}
	}
	return opts, nil
}

func loadModelSnapshot(workDir string, refresh modelregistry.RefreshMode) (modelregistry.ModelSnapshot, *agentConfig.Config, *modelcatalog.Catalog, *discoverycache.Cache, error) {
	cfg, err := agentConfig.Load(workDir)
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	cat, err := cfg.LoadModelCatalog()
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	root, err := modelCacheRoot()
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	cache := &discoverycache.Cache{Root: root}
	snapshot, err := modelregistry.AssembleWithOptions(context.Background(), cfg, cat, cache, modelregistry.AssembleOptions{Refresh: refresh})
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	return snapshot, cfg, cat, cache, nil
}

func modelCacheRoot() (string, error) {
	if override := strings.TrimSpace(os.Getenv("FIZEAU_CACHE_DIR")); override != "" {
		return override, nil
	}
	cacheDir, err := os.UserCacheDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(cacheDir, "fizeau"), nil
}

func cmdModelsList(snapshot modelregistry.ModelSnapshot, opts modelsCommandOptions) int {
	models := filterModelRows(snapshot.Models, opts)
	if opts.JSON {
		out := snapshot
		out.Models = models
		data, err := json.MarshalIndent(out, "", "  ")
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %s\n", err)
			return 1
		}
		fmt.Println(string(data))
		return 0
	}

	tw := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "PROVIDER\tMODEL\tFAMILY\tVERSION\tTIER\tPOWER\tCOST/M\tSTATUS\tCATALOG QUOTA\tRUNTIME QUOTA\tAUTO")
	for _, model := range models {
		fmt.Fprintf(tw, "%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n",
			model.Provider,
			model.ID,
			emptyDash(model.Family),
			formatVersion(model.Version),
			formatTier(model.Tier),
			formatModelPower(model.Power),
			formatModelCost(model.CostInputPerM, model.CostOutputPerM),
			model.Status,
			emptyDash(model.QuotaPool),
			formatRuntimeQuota(model.QuotaRemaining),
			formatAuto(model),
		)
	}
	_ = tw.Flush()
	return 0
}

func filterModelRows(models []modelregistry.KnownModel, opts modelsCommandOptions) []modelregistry.KnownModel {
	filtered := make([]modelregistry.KnownModel, 0, len(models))
	for _, model := range models {
		if opts.Provider != "" && model.Provider != opts.Provider {
			continue
		}
		if opts.PowerMin > 0 && model.Power < opts.PowerMin {
			continue
		}
		if opts.PowerMax > 0 && model.Power > opts.PowerMax {
			continue
		}
		filtered = append(filtered, model)
	}
	if !opts.IncludeNoise {
		filtered = suppressModelNoise(filtered)
	}
	sort.SliceStable(filtered, func(i, j int) bool {
		if filtered[i].Provider != filtered[j].Provider {
			return filtered[i].Provider < filtered[j].Provider
		}
		if filtered[i].Family != filtered[j].Family {
			return filtered[i].Family < filtered[j].Family
		}
		if cmp := compareVersions(filtered[i].Version, filtered[j].Version); cmp != 0 {
			return cmp > 0
		}
		return filtered[i].ID < filtered[j].ID
	})
	return filtered
